def compute(vars):
    shares = vars["v1"]
    average_price = vars["v2"]
    cash_used = shares * average_price
    cash_used_millions = cash_used / 1_000_000

    return {
        "value": cash_used_millions,
        "trace": {
            "shares": shares,
            "average_price": average_price,
            "cash_used": cash_used,
            "cash_used_millions": cash_used_millions,
            "output_meta": {
                "currency": "USD",
                "scale": "millions",
                "unit": "currency"
            }
        }
    }
